package com.portfolio.fraud.entity;
import jakarta.persistence.*;
@Entity @Table(name="fraud_rule_results") public class FraudRuleResult { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="fraud_analysis_id",nullable=false) private FraudAnalysis analysis; @Column(name="rule_name",nullable=false) private String ruleName; @Column(nullable=false,length=500) private String reason; @Enumerated(EnumType.STRING) @Column(nullable=false) private RiskLevel severity; @Column(name="score_contribution",nullable=false) private int scoreContribution; protected FraudRuleResult(){} public FraudRuleResult(String n,String r,RiskLevel s,int p){ruleName=n;reason=r;severity=s;scoreContribution=p;} void setAnalysis(FraudAnalysis a){analysis=a;} public String getRuleName(){return ruleName;} public String getReason(){return reason;} public RiskLevel getSeverity(){return severity;} public int getScoreContribution(){return scoreContribution;} }
